// Set CREATED_BY after import (Auth0 subject).
// Normalizes _id to hex for MongoDB update (see workflow sticky note).
const CREATED_BY = 'auth0|REPLACE_WITH_YOUR_AUTH0_SUBJECT';
const now = new Date().toISOString();

function toHexId(v) {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  if (typeof v.toHexString === 'function') return v.toHexString();
  if (typeof v.toString === 'function') {
    const s = v.toString();
    if (/^[a-f0-9]{24}$/i.test(s)) return s;
  }
  if (v.$oid && typeof v.$oid === 'string') return v.$oid;
  const buf = v.buffer ?? v.id ?? v;
  if (buf && (Array.isArray(buf) || (typeof buf.length === 'number' && typeof buf[0] === 'number') || buf.data)) {
    const arr = buf.data || buf;
    if (arr && typeof arr.length === 'number') {
      const bytes = [];
      for (let i = 0; i < arr.length; i++) bytes.push(Number(arr[i]).toString(16).padStart(2, '0'));
      const hex = bytes.join('');
      if (/^[a-f0-9]{24}$/i.test(hex)) return hex;
    }
  }
  return String(v);
}

function parseExperience(v) {
  if (typeof v === 'number' && Number.isFinite(v)) return Math.max(0, Math.floor(v));
  if (typeof v === 'string' && v.trim()) {
    const m = v.match(/(\d+)\s*\+?\s*(?:to|-|–)\s*(\d+)/i);
    if (m) return Math.max(0, parseInt(m[1], 10));
    const n = parseInt(v.replace(/\D/g, ''), 10);
    if (!Number.isNaN(n)) return Math.max(0, n);
  }
  return 0;
}

function parseSalaryToNumber(raw) {
  if (raw == null || raw === '') return 0;
  if (typeof raw === 'number' && Number.isFinite(raw)) return Math.max(0, Math.round(raw));
  const s = String(raw);
  const nums = [];
  const re = /\$?\s*([\d,]+(?:\.\d+)?)\s*k?/gi;
  let mm;
  while ((mm = re.exec(s)) !== null) {
    let v = parseFloat(mm[1].replace(/,/g, ''));
    if (/k\b/i.test(mm[0])) v *= 1000;
    if (!Number.isNaN(v)) nums.push(v);
  }
  if (nums.length === 0) return 0;
  if (nums.length >= 2) return Math.round((nums[0] + nums[1]) / 2);
  return Math.round(nums[0]);
}

function f500Str(v) {
  if (v === true) return 'Yes';
  if (v === false) return 'No';
  const t = String(v ?? '').trim().toLowerCase();
  if (t === 'yes') return 'Yes';
  if (t === 'no') return 'No';
  return '';
}

return items.map(({ json: doc }) => {
  const d = doc.data || {};
  const dateVal = d.date ? new Date(d.date) : new Date(doc.createdAt || now);
  const idHex = toHexId(doc._id);
  if (!idHex || !/^[a-f0-9]{24}$/i.test(idHex)) {
    console.warn('Prepare: doc._id is not a valid hex ObjectId; update will likely no-op.', doc._id);
  }
  return {
    json: {
      _id: idHex,
      'data.status': 'active',
      jobId: d.jobId,
      jobUrl: d.jobUrl ?? '',
      jobSourceURL: d.jobUrl ?? '',
      jobTitle: d.jobTitle ?? '',
      companyName: d.companyName ?? '',
      jobDescription: d.jobDescription ?? '',
      jobCategory: d.jobCategory ?? '',
      location: String(d.location ?? '').trim(),
      salary: parseSalaryToNumber(d.salary),
      sectorIndustry: String(d.sectorIndustry ?? '').trim(),
      f500: f500Str(d.f500),
      date: dateVal.toISOString(),
      createdBy: CREATED_BY,
      job_creation_type: 'automation',
      status: 'active',
      isFlagged: Boolean(d.isFlagged),
      jobExperience: parseExperience(d.jobExperience),
      __v: 0,
      createdAt: now,
      updatedAt: now,
    },
  };
});

const prepared = $('Prepare update + job row').all();
if (prepared.length !== items.length) {
  throw new Error(`Shape: Prepare has ${prepared.length} items but Update passed ${items.length}`);
}
function pickJob(p) {
  return {
    jobId: p.jobId,
    jobUrl: p.jobUrl,
    jobSourceURL: p.jobSourceURL,
    jobTitle: p.jobTitle,
    companyName: p.companyName,
    jobDescription: p.jobDescription,
    jobCategory: p.jobCategory,
    location: p.location,
    salary: p.salary,
    sectorIndustry: p.sectorIndustry,
    f500: p.f500,
    date: p.date,
    createdBy: p.createdBy,
    job_creation_type: p.job_creation_type,
    status: p.status,
    isFlagged: p.isFlagged,
    jobExperience: p.jobExperience,
    __v: p.__v,
    createdAt: p.createdAt,
    updatedAt: p.updatedAt,
  };
}
return prepared.map(({ json: p }) => ({ json: pickJob(p) }));

// Defensive second layer: drops rows the server's shouldKeepExtractedJobRow
// already rejects, plus any junk that slipped through (legacy docs migrated
// before the server filter was deployed). Mirrors server/src/services/automation.ts.
//
// Also resets workflow static data here so a crash mid-loop in a previous run
// doesn't cause duplicate inserts on the next scheduled run.
const staticData = $getWorkflowStaticData('global');
staticData.processedJobs = [];

const NON_JOB_URL_HOST = /^(?:legal|privacy|policy|policies|safety|cookies?|consent|imprint|impressum|sitemap|gdpr|ccpa)\./i;
const NON_JOB_URL_PATH = /\/(?:privacy(?:[-_]?policy)?|cookies?|cookie[-_]?policy|cookie[-_]?notice|cookie[-_]?settings|cookie[-_]?preferences|legal|terms(?:[-_]?of[-_]?(?:service|use))?|gdpr|ccpa|consent|safety|imprint|impressum|sitemap|accessibility|do[-_]?not[-_]?sell|opt[-_]?out)(?:\/|$|[?#])/i;
const PAGINATION_TITLE = /^(?:«+\s*)?(?:first|previous|prev|next|last)(?:\s+page)?(?:\s*»+)?$|^last\s+page\b|^page\s+\d+\s*(?:of\s*\d+)?$|^\d+\s*\/\s*\d+$|^«+$|^»+$/i;
const COOKIE_BANNER_TITLE = /^(?:learn more about (?:this|the) (?:provider|cookie|partner)|about (?:this|the) (?:provider|cookie|partner)|cookie\s*(?:policy|preferences|settings|notice|details?)|manage\s+(?:cookies?|preferences?|consent)|opt[-_ ]?out|accept(?:\s+(?:all|cookies?))?|reject\s+(?:all|cookies?)?|do not sell(?:\s+my(?:\s+personal)?\s+(?:info(?:rmation)?|data))?|view\s+(?:cookies?|preferences?)|show\s+(?:cookies?|preferences?))$/i;

// Cookie / tracker identifier patterns (snake_case, all-lowercase, all-uppercase 5+).
const COOKIE_IDENT_BODY = /^(?:[^\s]*_[^\s]*|[a-z][a-z0-9.]+|[A-Z][A-Z0-9_]{4,})$/;
const COOKIE_IDENT_SUFFIX = /\s*\[x?\d+\]\s*$/i;
function isCookieIdent(s) {
  const stripped = String(s ?? '').replace(COOKIE_IDENT_SUFFIX, '').trim();
  if (!stripped || /\s/.test(stripped)) return false;
  return COOKIE_IDENT_BODY.test(stripped);
}

// Cookie purpose description sentences ("Used to ...", "Tracks the user ...", etc.).
const COOKIE_USED_TO = /^used\s+(?:to|by|for)\s+\w/i;
const COOKIE_VERB_DETERMINER = /^(?:registers?|maintains?|stores?|tracks?|saves?|loads?|allows?|enables?|provides?|determines?|contains?|holds?|identifies|detects?|handles?|sets?|updates?|records?|counts?|measures?|distinguishes?|collects?|preserves?)\s+(?:to|by|the|which|user|whether|if|a|an|in|for|on|with|via|when|that|user's|user\u2019s|browser|session|cookie|data|info|visit(?:or|ors)?)/i;
const COOKIE_VERB_LONG = /^(?:used|registers?|maintains?|stores?|tracks?|saves?|loads?|allows?|enables?|provides?|determines?|contains?|holds?|identifies|detects?|handles?|sets?|updates?|records?|counts?|measures?|distinguishes?|collects?|preserves?)(?:\s+\S+){5,}/i;
function isCookieSentence(s) {
  const t = String(s ?? '');
  return COOKIE_USED_TO.test(t) || COOKIE_VERB_DETERMINER.test(t) || COOKIE_VERB_LONG.test(t);
}

const COOKIE_EXPIRY_COMPANY = /^(?:pending|session|persistent|1st party|3rd party|http(?:\s+only)?)$/i;

function keep(d) {
  const url = String(d.jobUrl ?? d.url ?? d.link ?? '').trim();
  const title = String(d.jobTitle ?? d.title ?? '').trim();
  const description = String(d.jobDescription ?? d.description ?? '').trim();
  const company = String(d.companyName ?? d.company ?? '').trim();

  if (!url && !title) return false;

  if (title) {
    if (PAGINATION_TITLE.test(title)) return false;
    if (COOKIE_BANNER_TITLE.test(title)) return false;
    if (isCookieIdent(title)) return false;
    if (isCookieSentence(title)) return false;
  }

  if (description && isCookieSentence(description)) {
    if (!url || COOKIE_EXPIRY_COMPANY.test(company)) return false;
  }

  if (company && COOKIE_EXPIRY_COMPANY.test(company) && !url) return false;

  if (url) {
    let host = '';
    let pathAndQuery = '';
    try {
      const u = new URL(url, 'https://example.invalid');
      host = u.hostname;
      pathAndQuery = u.pathname + (u.search || '');
    } catch (e) {
      pathAndQuery = url;
    }
    if (host && NON_JOB_URL_HOST.test(host)) return false;
    if (pathAndQuery && NON_JOB_URL_PATH.test(pathAndQuery)) return false;
    if (/sia-partners\.com/i.test(url) && /\/our-capabilities\//i.test(url)) return false;
  }

  return true;
}

const items = $input.all();
const kept = items.filter(item => keep(item.json || {}));
const dropped = items.length - kept.length;
if (dropped > 0) {
  console.log(`Filter junk rows: dropped ${dropped} of ${items.length} (cookie banners / cookie idents / tracker descriptions / pagination / privacy URLs).`);
}
return kept;

const items = $input.all();
await new Promise(resolve => setTimeout(resolve, 500));
return items;

const items = $input.all();

function salaryFromJobPosting(bs) {
  if (!bs || typeof bs !== 'object') return null;
  const val = bs.value;
  if (typeof val === 'number' && Number.isFinite(val)) return Math.round(val);
  if (val && typeof val === 'object') {
    const min = Number(val.minValue);
    const max = Number(val.maxValue);
    const unit = String(val.unitText || '').toUpperCase();
    let mult = 1;
    if (unit.includes('HOUR')) mult = 2080;
    if (Number.isFinite(min) && Number.isFinite(max)) return Math.round(((min + max) / 2) * mult);
    if (Number.isFinite(min)) return Math.round(min * mult);
    if (Number.isFinite(max)) return Math.round(max * mult);
  }
  if (typeof val === 'string' && /^[\d.]/.test(val.trim())) {
    const n = parseFloat(val.replace(/[^\d.]/g, ''));
    if (Number.isFinite(n)) return Math.round(n);
  }
  return null;
}

function locationFromJobPosting(jp) {
  const jl = jp.jobLocation;
  if (!jl) return null;
  if (typeof jl === 'string') return jl.trim() || null;
  const addr = jl.address || jl;
  if (typeof addr === 'string') return addr.trim() || null;
  if (addr && typeof addr === 'object') {
    const parts = [];
    if (addr.addressLocality) parts.push(String(addr.addressLocality).trim());
    if (addr.addressRegion) parts.push(String(addr.addressRegion).trim());
    if (parts.length) return parts.join(', ');
    if (addr.streetAddress) return String(addr.streetAddress).trim();
  }
  return null;
}

function experienceFromJobPosting(jp) {
  const er = jp.experienceRequirements;
  if (typeof er === 'string') {
    const mm = er.match(/(\d+)\s*\+?\s*(?:to|-|–)\s*(\d+)\s*years?/i);
    if (mm) return Math.max(0, parseInt(mm[1], 10));
    const m1 = er.match(/(\d+)\s*\+?\s*years?/i);
    if (m1) return Math.max(0, parseInt(m1[1], 10));
    const m2 = er.match(/(\d+)\s*\+\s*years?/i);
    if (m2) return Math.max(0, parseInt(m2[1], 10));
  }
  if (er && typeof er === 'object' && er.monthsOfExperience != null) {
    const mo = Number(er.monthsOfExperience);
    if (Number.isFinite(mo) && mo > 0) return Math.max(0, Math.floor(mo / 12));
  }
  return null;
}

return items.map(item => {
  const result = {
    apply_url: null,
    scraped_jobTitle: null,
    scraped_companyName: null,
    scraped_jobDescription: null,
    scraped_location: null,
    scraped_salary: null,
    scraped_experienceYears: null,
  };
  try {
    const html = String(item.json?.data ?? '');
    if (!html) return { json: result };

    const jsonLdBlocks = [...html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
    let jobPosting = null;
    for (const block of jsonLdBlocks) {
      try {
        const parsed = JSON.parse(block[1]);
        const candidates = Array.isArray(parsed) ? parsed : [parsed];
        for (const c of candidates) {
          if (c['@type'] === 'JobPosting') { jobPosting = c; break; }
          if (c['@graph']) {
            const found = c['@graph'].find(g => g['@type'] === 'JobPosting');
            if (found) { jobPosting = found; break; }
          }
        }
        if (jobPosting) break;
      } catch {}
    }

    if (jobPosting) {
      result.scraped_jobTitle = jobPosting.title || null;
      const org = jobPosting.hiringOrganization;
      if (org) result.scraped_companyName = typeof org === 'string' ? org : (org.name || null);
      if (jobPosting.description) {
        result.scraped_jobDescription = jobPosting.description.replace(/<[^>]*>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/\s+/g, ' ').trim().slice(0, 8000);
      }
      if (jobPosting.url) result.apply_url = jobPosting.url;
      const loc = locationFromJobPosting(jobPosting);
      if (loc) result.scraped_location = loc;
      const sal = salaryFromJobPosting(jobPosting.baseSalary);
      if (sal != null) result.scraped_salary = sal;
      const ex = experienceFromJobPosting(jobPosting);
      if (ex != null) result.scraped_experienceYears = ex;
    }

    if (!result.apply_url) {
      const rawText = html.replace(/<[^>]*>/g, '');
      const applyMatch = rawText.match(/"apply_url"\s*:\s*"([^"]+)"/);
      if (applyMatch && applyMatch[1]) {
        let url = applyMatch[1];
        url = url.replace(/\\u([0-9a-fA-F]{4})/g, (m, h) => String.fromCharCode(parseInt(h, 16)));
        url = url.replace(/\\n/g, '\n').replace(/\\r/g, '\r').replace(/\\t/g, '\t').replace(/\\\\/g, '\\').replace(/\\"/g, '"');
        result.apply_url = url;
      }
    }

    const metaVal = (prop) => {
      const m = html.match(new RegExp('<meta[^>]+(?:property|name)=["\']' + prop + '["\'][^>]+content=["\']([^"\']+)["\']', 'i'))
        || html.match(new RegExp('<meta[^>]+content=["\']([^"\']+)["\'][^>]+(?:property|name)=["\']' + prop + '["\']', 'i'));
      return m ? m[1].trim() : null;
    };
    if (!result.scraped_jobTitle) result.scraped_jobTitle = metaVal('og:title');
    if (!result.scraped_companyName) result.scraped_companyName = metaVal('og:site_name');
    if (!result.scraped_jobDescription) {
      const ogDesc = metaVal('og:description');
      if (ogDesc && ogDesc.length > 30) result.scraped_jobDescription = ogDesc;
    }

    if (!result.scraped_jobTitle) {
      const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
      if (titleMatch) {
        let t = titleMatch[1].trim();
        t = t.replace(/\s*[\|\u2013\u2014-]\s*(?:Amazon\.?jobs?|Google\s*Careers?|Sia\s*Partners|LinkedIn|Indeed|Glassdoor|Careers?|Jobs?)\s*$/i, '').trim();
        if (t) result.scraped_jobTitle = t;
      }
    }

    if (!result.scraped_jobTitle) {
      const h1Match = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
      if (h1Match) {
        const h1Text = h1Match[1].replace(/<[^>]*>/g, '').trim();
        if (h1Text && h1Text.length < 200) result.scraped_jobTitle = h1Text;
      }
    }

    if (!result.scraped_companyName) {
      const urlMatch = html.match(/<meta[^>]+(?:property|name)=['"]og:url['"][^>]+content=['"]([^'"]+)['"]/i)
        || html.match(/<link[^>]+rel=['"]canonical['"][^>]+href=['"]([^'"]+)['"]/i);
      if (urlMatch) {
        try {
          const hostname = new URL(urlMatch[1]).hostname;
          const hostMap = {
            'www.amazon.jobs': 'Amazon', 'amazon.jobs': 'Amazon',
            'www.google.com': 'Google', 'careers.google.com': 'Google',
            'www.sia-partners.com': 'Sia Partners', 'sia-partners.com': 'Sia Partners',
            'www.linkedin.com': 'LinkedIn', 'www.microsoft.com': 'Microsoft',
            'careers.microsoft.com': 'Microsoft', 'www.meta.com': 'Meta',
            'www.apple.com': 'Apple', 'jobs.apple.com': 'Apple',
          };
          result.scraped_companyName = hostMap[hostname]
            || hostname.replace(/^www\./, '').replace(/\.(com|org|net|io|jobs|careers)$/, '').replace(/[-_]/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
        } catch {}
      }
    }
  } catch (error) {}
  return { json: result };
});

