function parseLlmJson(output) {
  const s = String(output ?? '').trim();
  if (!s) return null;
  try { return JSON.parse(s); } catch (_) {}
  const fence = s.match(/```(?:json)?\s*(\{[\s\S]*?\})\s*```/i);
  if (fence) try { return JSON.parse(fence[1]); } catch (_) {}
  const brace = s.match(/\{[\s\S]*\}/);
  if (brace) try { return JSON.parse(brace[0]); } catch (_) {}
  return null;
}

function numOrZero(v) {
  if (v == null || v === '') return 0;
  const x = Number(v);
  return Number.isFinite(x) && x >= 0 ? Math.round(x) : 0;
}

const m = $input.item.json;
const loop = $('Loop Over Items').item.json;
const llm = parseLlmJson(m.output);

function badPortalCompany(s) {
  const t = String(s ?? '').trim();
  if (!t) return true;
  return /^(careers?|jobs?|hiring|job\s*board|greenhouse|lever|workday|icims|taleo|smartrecruiters|jobvite|bamboohr|successfactors|workable|ashby)$/i.test(t);
}
function pickJobTitle(llm, scraped, maxun) {
  const L = llm && typeof llm.jobTitle === 'string' ? llm.jobTitle.trim() : '';
  const S = scraped ? String(scraped).trim() : '';
  const M = maxun ? String(maxun).trim() : '';
  if (L.length >= 4) return L;
  if (S.length >= 4) return S;
  if (M.length >= 4) return M;
  return L || S || M || '';
}
function pickCompanyName(llm, scraped, maxun) {
  const L = llm && typeof llm.companyName === 'string' ? llm.companyName.trim() : '';
  const S = scraped ? String(scraped).trim() : '';
  const M = maxun ? String(maxun).trim() : '';
  if (L && !badPortalCompany(L)) return L;
  if (S && !badPortalCompany(S)) return S;
  if (M && !badPortalCompany(M)) return M;
  return L || S || M || '';
}

const scrapedTitle = m.scraped_jobTitle && String(m.scraped_jobTitle).trim();
const scrapedCo = m.scraped_companyName && String(m.scraped_companyName).trim();
const applyUrl = m.apply_url && String(m.apply_url).trim();

const rawOut = String(m.output ?? '').trim();
const llmReq = llm && typeof llm.requirements === 'string' ? llm.requirements.trim() : '';
const useLlmReq = llmReq && !/^didn't\s*find/i.test(llmReq);
const scrapedDesc = m.scraped_jobDescription && String(m.scraped_jobDescription).trim();
const maxDesc = String(loop.jobDescription ?? '').trim();

let jobDescription = maxDesc;
if (useLlmReq) jobDescription = llmReq;
else if (scrapedDesc) jobDescription = scrapedDesc;
else if (!llm && rawOut && !/^didn't\s*find/i.test(rawOut)) jobDescription = rawOut;

const llmLoc = llm && typeof llm.location === 'string' ? llm.location.trim() : '';
const scrapedLoc = m.scraped_location && String(m.scraped_location).trim();
const location = llmLoc || scrapedLoc || String(loop.location ?? '').trim();

const llmSal = llm != null && llm.salaryAnnualUSD != null && llm.salaryAnnualUSD !== ""
  ? numOrZero(llm.salaryAnnualUSD)
  : null;
const scrapedSal = m.scraped_salary != null && m.scraped_salary !== "" ? numOrZero(m.scraped_salary) : null;
const loopSal = numOrZero(loop.salary);
const salary = (llmSal != null && llmSal > 0) ? llmSal : (scrapedSal != null && scrapedSal > 0) ? scrapedSal : loopSal;

let jobExperience = 0;
if (llm && llm.minYearsExperience != null && llm.minYearsExperience !== '') {
  const x = Number(llm.minYearsExperience);
  if (Number.isFinite(x) && x >= 0) jobExperience = Math.floor(x);
} else if (m.scraped_experienceYears != null && m.scraped_experienceYears !== '') {
  const x = Number(m.scraped_experienceYears);
  if (Number.isFinite(x) && x >= 0) jobExperience = Math.floor(x);
} else {
  const x = Number(loop.jobExperience);
  jobExperience = Number.isFinite(x) && x >= 0 ? Math.floor(x) : 0;
}

return {
  json: {
    jobId: loop.jobId,
    jobUrl: applyUrl || loop.jobUrl,
    jobSourceURL: loop.jobSourceURL,
    jobTitle: pickJobTitle(llm, scrapedTitle, loop.jobTitle),
    companyName: pickCompanyName(llm, scrapedCo, loop.companyName),
    jobDescription,
    jobCategory: loop.jobCategory,
    location,
    salary,
    sectorIndustry: String(loop.sectorIndustry ?? '').trim(),
    f500: loop.f500,
    date: loop.date,
    createdBy: loop.createdBy,
    job_creation_type: loop.job_creation_type,
    status: loop.status,
    isFlagged: loop.isFlagged,
    jobExperience,
    __v: loop.__v ?? 0,
    createdAt: loop.createdAt,
    updatedAt: loop.updatedAt,
  },
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedJobs) {
  staticData.processedJobs = [];
}

const items = $input.all();
for (const item of items) {
  staticData.processedJobs.push(item.json);
}

return items;

const staticData = $getWorkflowStaticData('global');
const jobs = staticData.processedJobs || [];

staticData.processedJobs = [];

return jobs.map(job => ({ json: job }));
